import './workspace-view-choice.css';

export type WorkspaceView = 'board' | 'list' | 'timeline';
type Props = { value: WorkspaceView; dispatch: (action: { type: 'workspace/viewChanged'; view: WorkspaceView }) => void };
const options: readonly { value: WorkspaceView; label: string }[] = [{ value: 'board', label: 'Board' }, { value: 'list', label: 'List' }, { value: 'timeline', label: 'Timeline' }];

export function WorkspaceViewChoice({ value, dispatch }: Props) {
  function choose(next: WorkspaceView) { if (next !== value) dispatch({ type: 'workspace/viewChanged', view: next }); }
  function move(event: React.KeyboardEvent<HTMLDivElement>) {
    const delta = event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1 : event.key === 'ArrowLeft' || event.key === 'ArrowUp' ? -1 : 0;
    if (!delta) return;
    event.preventDefault();
    const index = options.findIndex(option => option.value === value);
    const next = options[(index + delta + options.length) % options.length].value;
    choose(next);
    requestAnimationFrame(() => document.getElementById(`workspace-view-${next}`)?.focus());
  }
  return <div className="viewChoice" role="radiogroup" aria-label="Workspace view" onKeyDown={move}>
    {options.map(option => <button id={`workspace-view-${option.value}`} key={option.value} type="button" role="radio" aria-checked={value === option.value} tabIndex={value === option.value ? 0 : -1} onClick={() => choose(option.value)}>{option.label}</button>)}
  </div>;
}

