.viewChoice { display: inline-flex; padding: 2px; gap: 2px; border: 1px solid #c9c9d1; border-radius: .5rem; background: #f2f2f5; }
.viewChoice button { min-block-size: 1.75rem; padding: .2rem .65rem; border: 0; border-radius: .35rem; color: #4b4b55; background: transparent; font: inherit; font-size: .8125rem; line-height: 1; cursor: pointer; }
.viewChoice button[aria-checked='true'] { color: #18181b; background: #fff; box-shadow: 0 1px 3px rgb(0 0 0 / .14); font-weight: 600; }
.viewChoice button:hover { color: #18181b; }
.viewChoice button:focus-visible { outline: 2px solid #4f46e5; outline-offset: 2px; }
@media (forced-colors: active) { .viewChoice button[aria-checked='true'] { outline: 2px solid CanvasText; } }
